            Action<JObject> frontend=packet=>{packet["campaign"]=campaign;packet["visit"]=1;game.Enqueue(packet);game.Pump(.05);};
            Send(game,scene,campaign,"scene","exactX",0,"exactY",2);Latest(game);game.Inventory.Selected=3;
            frontend(HollowCraft.GameplayPackets.Interact(scene,5,5,2,2,true,0,2,5,1));var state=Latest(game);Check(((JArray)state["blocks"]).Any(b=>(int)b["x"]==2&&(int)b["y"]==2)&&!((JArray)state["blocks"]).Any(b=>(int)b["x"]==5),"Actual frontend right-click places at placeX/placeY instead of ignoring the operation");
            frontend(HollowCraft.GameplayPackets.Interact(scene,0,2,0,2,true,.5,3,0,-2));state=Latest(game);Check(((JArray)state["blocks"]).Any(b=>(int)b["x"]==0&&(int)b["y"]==2),"Jump-build accepts exact feet clearance using the action packet's current player coordinates");
