            frontend(HollowCraft.GameplayPackets.Use(scene,4,4,false,true,3,0));state=Latest(game);var arrow=((JArray)state["projectiles"]).Single();Check((string)arrow["kind"]=="minecraft:arrow"&&(double)arrow["vx"]==3&&!(bool)state["stats"]["using"],"Actual frontend release fires a fully charged arrow");
            double previousX=(double)arrow["x"];Send(game,scene,campaign,"projectileStep","steps",new JArray(new JObject{["entity"]=arrow["entity"],["uuid"]=arrow["uuid"],["age"]=arrow["age"]}));state=Latest(game);Check((double)state["projectiles"][0]["x"]>previousX,"Frontend projectile-step acknowledgement advances the visible arrow");
            Send(game,scene,campaign,"mode","mode","creative");Latest(game);Send(game,scene,campaign,"creativeCatalog");var catalog=Drain(game).Single(p=>(string)p["type"]=="catalog");var groups=(JArray)catalog["groups"];
