            var diamond=((JArray)catalog["items"]).First(i=>(string)i["id"]=="minecraft:diamond_sword");Send(game,scene,campaign,"creativeItem","catalogRevision",(int)catalog["revision"],"catalogIndex",(int)diamond["catalogIndex"],"destination","slot","slot",2,"count",64);state=Latest(game);Check((string)state["inventory"][2]["id"]=="minecraft:diamond_sword"&&(int)state["inventory"][2]["count"]==1,"Frontend creative number-key destination slot is honored");
            Send(game,scene,campaign,"creativeHotbar","action","save","slot",0);Latest(game);game.Inventory.Slots[2]=NativeStack.New("dirt");Send(game,scene,campaign,"creativeHotbar","action","load","slot",0);state=Latest(game);Check((string)state["inventory"][2]["id"]=="minecraft:diamond_sword","Creative C/X hotbar save and load preserve the complete stack");
        }
