    private static void RangedContracts(string root,string assets) {
        string path=Path.Combine(root,"ranged");using(var game=new NativeGame(path,assets)){
            const string room="room",campaign="ranged";Send(game,room,campaign,"scene","exactX",0,"exactY",2);Latest(game);
