            frontend(HollowCraft.GameplayPackets.Interact(room,2,3,2,3,false,0,2,1,0));Latest(game);for(int i=0;i<20;i++)game.Pump(.05);frontend(HollowCraft.GameplayPackets.Use(room,2,3,false,true,1,0));var state=Latest(game);var shot=(JObject)state["projectiles"][0];
