            Send(game,room,campaign,"nativeProjectileHit","entity",(int)shot["entity"],"uuid",(string)shot["uuid"],"request",1,"x",4,"y",3);state=Latest(game);Check((bool)state["projectiles"][0]["grounded"],"Solid block collision anchors an arrow instead of allowing terrain tunneling");
            game.Inventory.Slots[0]=NativeStack.New("crossbow");game.Inventory.Slots[0].Data["Charged"]=true;game.Inventory.Slots[0].Data["HollowCraftLoadedArrow"]=NativeStack.New("arrow").Json();game.Inventory.Slots[0].Data["Enchantments"]=new JArray(new JObject{["id"]="minecraft:multishot",["lvl"]=1},new JObject{["id"]="minecraft:piercing",["lvl"]=1});frontend(HollowCraft.GameplayPackets.Interact(room,2,3,2,3,false,0,2,1,0));state=Latest(game);var volley=((JArray)state["projectiles"]).OfType<JObject>().Where(p=>(bool?)p["grounded"]!=true).ToArray();Check(volley.Length==3&&volley.Select(p=>(double)p["vy"]).Distinct().Count()==3&&(int)state["inventory"][0]["damage"]==3,"Multishot produces three distinct flight trajectories and correct durability cost");
